func testStore(t *testing.T) *Store {
	t.Helper()
	s, err := OpenStore(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { s.DB.Close() })
	return s
}
func TestPythonFernetCompatibility(t *testing.T) {
	key, _ := base64.URLEncoding.DecodeString("MDEyMzQ1Njc4OWFiY2RlZjAxMjM0NTY3ODlhYmNkZWY=")
	s := &Store{key: key}
	// Generated by cryptography.fernet.Fernet.encrypt_at_time in the old backend.
	token := "gAAAAABlU_EAfYuq2WR3zynQxcetxShaQYWoefry8rHm24dV-Ice8x8hxJy5XSKWkL1FIEP4-PVcazbkp-k3jjQLkyWVh2xJXplge0PGKLo-yqmLmCeYhPM="
	plain, err := s.Decrypt(token)
	if err != nil || plain != "user@pve!orbit=example-secret" {
		t.Fatalf("legacy token: %q %v", plain, err)
	}
	for _, value := range []string{"", "one block of txt!", strings.Repeat("x", 500), "ümläüt"} {
		encrypted, err := s.Encrypt(value)
		if err != nil {
			t.Fatal(err)
		}
		got, err := s.Decrypt(encrypted)
		if err != nil || got != value {
			t.Fatalf("roundtrip: %q %v", got, err)
		}
	}
	raw, _ := base64.URLEncoding.DecodeString(token)
	raw[30] ^= 1
	if _, err = s.Decrypt(base64.URLEncoding.EncodeToString(raw)); err == nil {
		t.Fatal("tampered ciphertext accepted")
	}
	for _, bad := range []string{"", "garbage", base64.URLEncoding.EncodeToString(make([]byte, 73))} {
		if _, err = s.Decrypt(bad); err == nil {
			t.Fatal("malformed token accepted")
		}
	}
}
func TestPythonScryptCompatibility(t *testing.T) {
	saved := "00112233445566778899aabbccddeeff:fb606bcd636b3add25718816e791998fbc116679a78eceda34f79c31182ed2b6af98c7b2ddfa137ac803a2ba3fee8424e85eed03bba4c49ba84817af3e839a90"
	if !CheckPassword("password-for-test", saved) {
		t.Fatal("Python password not accepted")
	}
	if CheckPassword("wrong", saved) || CheckPassword("x", "broken") {
		t.Fatal("invalid password accepted")
	}
}
func TestLegacySchemaMigration(t *testing.T) {
	dir := t.TempDir()
	key := []byte("MDEyMzQ1Njc4OWFiY2RlZjAxMjM0NTY3ODlhYmNkZWY=")
	if err := os.WriteFile(filepath.Join(dir, "master.key"), key, 0600); err != nil {
		t.Fatal(err)
	}
	db, err := sql.Open("sqlite", filepath.Join(dir, "orbit.db"))
	if err != nil {
		t.Fatal(err)
	}
	_, err = db.Exec(`CREATE TABLE connections(id TEXT PRIMARY KEY,name TEXT NOT NULL,url TEXT NOT NULL,token TEXT NOT NULL,created REAL NOT NULL); INSERT INTO connections VALUES('legacy','Cluster','https://pve:8006','gAAAAABlU_EAfYuq2WR3zynQxcetxShaQYWoefry8rHm24dV-Ice8x8hxJy5XSKWkL1FIEP4-PVcazbkp-k3jjQLkyWVh2xJXplge0PGKLo-yqmLmCeYhPM=',1);`)
	db.Close()
	if err != nil {
		t.Fatal(err)
	}
	s, err := OpenStore(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer s.DB.Close()
	c, err := s.Connection("legacy")
	if err != nil || c.Kind != "pve" || len(c.Endpoints) != 0 {
		t.Fatalf("migration: %+v %v", c, err)
	}
	got, _ := os.ReadFile(filepath.Join(dir, "master.key"))
	if !bytes.Equal(key, got) {
		t.Fatal("master key changed")
	}
}
func TestWrongKeyFailsWithoutReplacement(t *testing.T) {
	dir := t.TempDir()
	s, err := OpenStore(dir)
	if err != nil {
		t.Fatal(err)
	}
	token, _ := s.Encrypt("user@pve!id=secret")
	err = s.SaveConnection(Connection{ID: "c", Name: "c", URL: "https://pve", Token: token, Kind: "pve", Endpoints: []string{}}, true)
	s.DB.Close()
	if err != nil {
		t.Fatal(err)
	}
	wrong := []byte(base64.URLEncoding.EncodeToString(bytes.Repeat([]byte{7}, 32)))
	if err = os.WriteFile(filepath.Join(dir, "master.key"), wrong, 0600); err != nil {
		t.Fatal(err)
	}
	if store, err := OpenStore(dir); err == nil {
		store.DB.Close()
		t.Fatal("wrong key accepted")
	}
	got, _ := os.ReadFile(filepath.Join(dir, "master.key"))
	if !bytes.Equal(got, wrong) {
		t.Fatal("key overwritten")
	}
}

func TestMissingKeyDoesNotGenerateReplacement(t *testing.T) {
	dir := t.TempDir()
	store, err := OpenStore(dir)
	if err != nil {
		t.Fatal(err)
	}
	store.DB.Close()
	path := filepath.Join(dir, "master.key")
	if err = os.Remove(path); err != nil {
		t.Fatal(err)
	}
	if next, err := OpenStore(dir); err == nil {
		next.DB.Close()
		t.Fatal("missing key ignored")
	}
	if _, err = os.Stat(path); !os.IsNotExist(err) {
		t.Fatal("replacement key generated")
	}
}
